mkdir -p /workspace/tmp/t && cat > /workspace/tmp/t/codec_test.c <<'EOF'
#include "epic_clean.h"
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
int main(int argc,char**argv){
  /* read hex frames from stdin lines: "rank psn payloadhex|ACK" -> print built hex */
  char line[65536];
  while(fgets(line,sizeof line,stdin)){
    int rank; unsigned psn; char kind[16]; static unsigned char pay[8192]; size_t plen=0;
    char *sp1=strchr(line,' '); if(!sp1) continue; *sp1++=0;
    char *sp2=strchr(sp1,' '); if(!sp2) continue; *sp2++=0;
    char *rest=sp2;
    rank=atoi(line); psn=(unsigned)strtoul(rest?sp1:sp1,NULL,10);
    char *nl=strchr(rest,'\n'); if(nl)*nl=0;
    if(strcmp(rest,"ACK")==0){ kind[0]=1; plen=0; }
    else { kind[0]=0; plen=strlen(rest)/2; for(size_t i=0;i<plen;i++){ unsigned v; sscanf(rest+2*i,"%2x",&v); pay[i]=(unsigned char)v; } }
    uint8_t hm[6]={2,0,0,0,0,0}, sm[6]={2,1,0,0,0,0}; hm[5]=rank+1; sm[5]=rank+1;
    uint32_t hip=htonl(0x0a000001u+rank), sip=htonl(0x0a000065u+rank);
    uint8_t frame[8192]; size_t len;
    if(kind[0]) len=epic_build_roce_ack(frame,sizeof frame,sm,hm,sip,hip,4791,4791,0x100u+rank,psn);
    else len=epic_build_roce_data_raw(frame,sizeof frame,sm,hm,sip,hip,4791,4791,0x100u+rank,psn,pay,plen);
    for(size_t i=0;i<len;i++) printf("%02x",frame[i]);
    printf("\n");
  }
  return 0;
}
EOF
cd /workspace/project && gcc -std=c11 -O2 -Iinclude /workspace/tmp/t/codec_test.c src/roce_packet.c -o /workspace/tmp/t/codec_test && echo built
